import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_tuned_cam_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_tuned_cam_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.967807907520099e+00, -3.892209797398154e+00, -3.786332160707760e+00, -3.639775497642848e+00, -3.440297919013696e+00, -3.175256262269640e+00, -2.834970331691505e+00, -2.418605051757563e+00, -1.941318334838680e+00, -1.435229384768786e+00, -9.356302127248817e-01, -6.089300777061007e-01, -5.167371922005870e-01, -4.158960419666026e-01, -2.773580038828434e-01, -1.351905509468214e-01, -3.178992349360410e-02, -3.930413570101395e-03, -5.101625931773049e-04, -6.225770790877009e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


